CREATE COLUMN TABLE "TEST_AP"."OBNH" ("IdNumber" INTEGER CS_INT NOT NULL , "ActKey" INTEGER CS_INT NOT NULL , "BSNum" INTEGER CS_INT NOT NULL , "BSDate" LONGDATE CS_LONGDATE NOT NULL , "Status" NVARCHAR(1) DEFAULT 'D', "Imported" NVARCHAR(1) DEFAULT 'Y', "StrtBlncF" DECIMAL(21,6) CS_FIXED, "EndBlncF" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "StrtBlncL" DECIMAL(21,6) CS_FIXED, "EndBlncL" DECIMAL(21,6) CS_FIXED, "FileCRC" NVARCHAR(32), "StmtGuid" NVARCHAR(32), "BSFileNum" NVARCHAR(50), "PeriodAbs" INTEGER CS_INT, "DfltBPL" INTEGER CS_INT, "OrigBSDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("IdNumber")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBNH_ACT_NUM_DT" ON "TEST_AP"."OBNH" ( "ActKey" ASC, "BSNum" ASC, "BSDate" ASC )